entries[240213] = { ["name"] = "Verhüllendes Manatuch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+389 [Beweglichkeit oder Stärke]\nAnlegen: Bei erlittenem Schaden besteht die Chance, dass die Verzauberungen des Tuchs Euer Geschick erhöhen und Euch 12 Sek. lang 1322 Vielseitigkeit verleihen.\nVerkaufspreis:" }
entries[240214] = { ["name"] = "Miniatursandgarten der Reshii", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+389 Intelligenz\nAnlegen: Eure Heilfähigkeiten haben eine Chance, Euch 5 Wirbel von 'Aufgewühlte Sande' zu verleihen, wobei jeder Wirbel Euch 513 Tempo gewährt. Alle 4 Sek. läuft ein Wirbel ab, bis 'Aufgewühlte Sande' verschwindet.\nVerkaufspreis:" }
