entries[240216] = { ["name"] = "Resonanzstein der K'areshi", ["text"] = "Handwerksmaterial\n\"Diese auffälligen Steine sind ein Beweis, dass die Schönheit der Natur selbst in der Ödnis beseht. Manchmal werden sie von Spielercharakteren mit Bergbaufertigkeit aus Erzvorkommen abgebaut. Sie können in Tazavesh eingetauscht oder im Auktionshaus an- und verkauft werden.\"\nVerkaufspreis:" }
